package org.springframework.samples.petclinic.util;

import java.util.Map;
import java.util.regex.Pattern;

/**
 * Validates an owner's 4-digit postcode against the postcode range of their city's region.
 * Ranges are keyed by the canonical region resolved via {@link CityRegions}; a city whose
 * region is {@link CityRegions#UNKNOWN} has no range and accepts any well-formed 4-digit
 * postcode.
 */
public final class Postcodes {

    /** A well-formed postcode is exactly four digits. */
    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private Postcodes() {
    }

    /** Whether {@code postcode} is exactly four digits. */
    public static boolean isWellFormed(String postcode) {
        return postcode != null && FOUR_DIGITS.matcher(postcode).matches();
    }

    /**
     * The canonical region whose postcode range contains {@code postcode}, or {@code null} when
     * the postcode is absent, malformed, or falls in no known range.
     */
    public static String regionOf(String postcode) {
        if (!isWellFormed(postcode)) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The region code derived solely from {@code postcode}: the region whose range contains it,
     * or {@link CityRegions#UNKNOWN} when the postcode is absent, malformed or in no known range.
     */
    public static String regionCode(String postcode) {
        String region = regionOf(postcode);
        return region != null ? region : CityRegions.UNKNOWN;
    }

    /**
     * Whether {@code postcode} is valid for {@code city}: it must be four digits and, when the
     * city's region has a known range, fall within it. A city with no known region accepts any
     * four-digit postcode.
     */
    public static boolean isValidForCity(String city, String postcode) {
        if (!isWellFormed(postcode)) {
            return false;
        }
        int[] range = REGION_RANGE.get(CityRegions.localityOf(city));
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }
}
=== CustomerCode ===
package org.springframework.samples.petclinic.util;

import java.util.Locale;
import java.util.Set;

/**
 * The owner customer-code identity, formatted {@code <REGION>-<HASH8>}: the region code
 * derived from the postcode, then the first eight upper-case hex characters of the SHA-256
 * digest of the owner's normalized telephone followed by their last name. Every value built
 * from the identity (membership number, check digit, locality) reads it back through here, so
 * the format lives in one place.
 */
public final class CustomerCode {

    private static final char SEPARATOR = '-';

    /** Number of leading hex characters of the digest kept as the identity's hash component. */
    private static final int HASH_LENGTH = 8;

    private CustomerCode() {
    }

    /**
     * Build the customer code {@code <region>-<HASH8>} for an owner in {@code region} whose
     * normalized telephone and last name hash to {@code HASH8}.
     */
    public static String of(String region, String normalizedTelephone, String lastName) {
        String hash8 = Sha256.hex(normalizedTelephone + lastName)
                .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
        return region + SEPARATOR + hash8;
    }

    /**
     * De-duplicate {@code customerCode} against the codes already {@code taken}. When it is free
     * the code is returned unchanged; otherwise {@code -<n>} is appended with the smallest
     * {@code n} of 2 or more that yields a code no owner already holds.
     */
    public static String deduplicate(String customerCode, Set<String> taken) {
        if (!taken.contains(customerCode)) {
            return customerCode;
        }
        for (int n = 2; ; n++) {
            String candidate = customerCode + SEPARATOR + n;
            if (!taken.contains(candidate)) {
                return candidate;
            }
        }
    }

    /**
     * The region component of {@code customerCode} (its identity locality), or
     * {@link CityRegions#UNKNOWN} when the code is absent or carries no region.
     */
    public static String regionOf(String customerCode) {
        if (customerCode == null) {
            return CityRegions.UNKNOWN;
        }
        int separator = customerCode.indexOf(SEPARATOR);
        String region = separator > 0 ? customerCode.substring(0, separator) : "";
        return region.isEmpty() ? CityRegions.UNKNOWN : region;
    }
}

